from fractions import Fraction
from sympy import symbols, solve

x = symbols("x", real=True)

def grid_max(V, a, b, n):
    best = a
    for i in range(n + 1):
        t = a + (b - a) * i / n
        if V(t) > V(best):
            best = t
    return best

def best_box(L, W, most):
    V = lambda t: t * (L - 2*t) * (W - 2*t)
    Vp = lambda t: 12*t**2 - 4*(L + W)*t + L*W
    best = 0
    for c in [most] + sorted(solve(Vp(x), x)):
        if 0 < c <= most and V(c) > V(best):
            best = c
    print(f"best cut {best}, volume {V(best)}")
    g = grid_max(V, 0, float(most), 1000)
    print(f"grid: {g:.3f}, {V(g):.3f}")

k = int(input())
for i in range(k):
    L, W, cap = [int(v) for v in input().split()]
    most = Fraction(L, 2)
    if W < L:
        most = Fraction(W, 2)
    if cap > 0:
        most = Fraction(cap)
    best_box(L, W, most)

