from fractions import Fraction

def pen(P, a, b):
    x = Fraction(P, 2*a)
    y = (P - a*x) / b
    print(f"x = {x}, y = {y}, area {x*y}")

def least(p, n, q):
    x = (q / (n * p)) ** (1 / (n + 1))
    print(f"x = {x:.3f}, least value {p * x**n + q / x:.3f}")

k = int(input())
for i in range(k):
    words = input().split()
    if words[0] == "pen":
        pen(int(words[1]), int(words[2]), int(words[3]))
    else:
        least(int(words[1]), int(words[2]), int(words[3]))

from fractions import Fraction
from sympy import symbols, solve, diff, sqrt

x = symbols("x", real=True)

def closest(f, a, b, start):
    D2 = lambda t: (t - a)**2 + (f(t) - b)**2
    cands = sorted(solve(diff(D2(x), x), x))
    if start == 0:
        keep = [0]
        for c in cands:
            if c > 0:
                keep.append(c)
        cands = keep
    best = D2(cands[0])
    for c in cands:
        if D2(c) < best:
            best = D2(c)
    for c in cands:
        if D2(c) == best:
            print(f"closest point ({c}, {f(c)}), distance {sqrt(best)}")

k = int(input())
for i in range(k):
    words = input().split()
    nums = [Fraction(w) for w in words[1:]]  # a slice: every word but the first
    if words[0] == "parabola":
        closest(lambda t: t**2, nums[0], nums[1], None)
    elif words[0] == "root":
        closest(lambda t: sqrt(t), nums[0], nums[1], 0)
    else:
        m, c = nums[0], nums[1]
        closest(lambda t: m*t + c, nums[2], nums[3], None)
